import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`chiropractic-audit`,heroTitle:`Audit your chiropractic practice in minutes`,heroSubtitle:`Perplexity Computer audits your site, benchmarks nearby competitors, and turns the biggest gaps into a ranked local-growth plan.`,inputUrlCta:`Run my audit`,inputUrlPlaceholder:`yourbusiness.com`,inputUrlPrefill:`Use {url} as the starting context for this workflow. Complete a full audit your chiropractic practice workflow. Benchmark strong competitors or adjacent examples where useful, then deliver a prioritized package with concrete recommendations, rewrites or drafts when relevant, and a concise summary of what to do next.`,heroOverlaySteps:[`Reviewing the website, trust signals, and local conversion flow`,`Benchmarking nearby competitors on positioning and proof`,`Finding the gaps most likely to hurt inquiries or bookings`,`Audit, rewrites, and growth plan ready to use`],generatingSteps:[`Reading {url} to understand the business, site, and local customer journey`,`Designing an agent to benchmark nearby competitors and visibility signals`,`Configuring recommendations for trust, local search, and conversion improvements`,`Packaging the work into a prioritized local-growth plan`],featureSectionTitle:`From local visibility gaps to a clearer growth plan`,featureCardTitles:[`Connects to your local ops workflow`,`Outputs your team can use next`],featureCardDescriptions:[`Computer breaks the work into site review, local presence analysis, competitor benchmarking, and prioritization so the audit reflects how customers actually choose a provider.`,`Docs, Sheets, CRM notes, and planning tools can stay connected so rewrites, review fixes, and campaign ideas are easier to execute.`,`Site fixes. Positioning ideas. Local visibility actions. Priority next steps. Computer gives your team the updates most likely to move inquiries and bookings.`],capabilitySectionTitle:`Your local growth analyst, on demand`,capabilitySectionSubtitle:`Paste the business context, step away, and come back to the fixes most likely to grow inquiries.`,capabilityCards:[{title:`Website and Funnel Audit`,description:`Computer can review the site, service pages, trust cues, and inquiry flow to show where prospects lose confidence or fail to convert.`},{title:`Local Visibility Review`,description:`Computer can assess reviews, listings, and local search signals so you see where stronger competitors are pulling ahead.`},{title:`Competitor Benchmarking`,description:`Computer can compare nearby operators on positioning, proof, offers, and booking experience to surface the highest-leverage gaps.`},{title:`Connect Your Tools`,description:`Computer can organize findings across Docs, Sheets, CRM notes, and planning tools so the handoff into execution is simpler.`},{title:`Priority Fixes`,description:`Computer can rank the changes most likely to improve inquiries, bookings, or close rate so your team knows what to tackle first.`},{title:`Refresh the Audit`,description:`Computer can revisit the business later and update the plan as reviews, rankings, or competitor positioning shift.`}]});export{t as default};
